 209→const ASSIGNMENT_TYPES = [
 210→  { value: "product", label: "Product ID" },
 211→  { value: "collection", label: "Collection ID" },
 212→  { value: "tag", label: "Product Tag" },
 213→  { value: "product_type", label: "Product Type" },
