 216→
 217→function formatDate(iso: string): string {
 218→  return new Date(iso).toLocaleDateString("en-US", {
 219→    month: "short",
 220→    day: "numeric",
 221→    year: "numeric",
 222→    hour: "2-digit",
 223→    minute: "2-digit",
 224→  });
 225→}
 226→
 227→function makeDefaultData(): ChartData {
 228→  return {
 229→    headers: ["Size", "Chest", "Waist", "Hips"],
 230→    units: { default: "in", available: ["in", "cm"] },
 231→    rows: [
 232→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 233→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 234→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 235→    ],
 236→  };
 237→}
 238→
 239→function parseChartData(raw: string): ChartData {
 240→  try {
 241→    const parsed = JSON.parse(raw) as ChartData;
 242→    if (
 243→      Array.isArray(parsed.headers) &&
 244→      parsed.units &&
 245→      Array.isArray(parsed.rows)
 246→    ) {
 247→      return parsed;
 248→    }
 249→  } catch {
 250→    // fall through
 251→  }
 252→  return makeDefaultData();
 253→}
