 255→// ---------------------------------------------------------------------------
 256→// Table Editor Component
 257→// ---------------------------------------------------------------------------
 258→
 259→interface TableEditorProps {
 260→  data: ChartData;
 261→  onChange: (data: ChartData) => void;
 262→}
 263→
 264→function TableEditor({ data, onChange }: TableEditorProps) {
 265→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 266→
 267→  const updateCell = (rowIndex: number, header: string, value: string) => {
 268→    const newRows = data.rows.map((row, i) => {
 269→      if (i !== rowIndex) return row;
 270→      return { ...row, [header]: value };
 271→    });
 272→    onChange({ ...data, rows: newRows });
 273→  };
 274→
 275→  const updateHeader = (headerIndex: number, value: string) => {
 276→    const oldHeader = data.headers[headerIndex];
 277→    const newHeaders = data.headers.map((h, i) => (i === headerIndex ? value : h));
 278→    const newRows = data.rows.map((row) => {
 279→      const newRow: Record<string, string> = {};
 280→      data.headers.forEach((h, i) => {
 281→        const key = i === headerIndex ? value : h;
 282→        newRow[key] = row[h] ?? "";
 283→      });
 284→      return newRow;
 285→    });
 286→    onChange({ ...data, headers: newHeaders, rows: newRows });
 287→    // suppress unused variable warning
 288→    void oldHeader;
 289→  };
 290→
 291→  const addRow = () => {
 292→    const emptyRow: Record<string, string> = {};
 293→    data.headers.forEach((h) => {
 294→      emptyRow[h] = "";
 295→    });
 296→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 297→  };
 298→
 299→  const removeRow = (rowIndex: number) => {
 300→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 301→  };
 302→
 303→  const addColumn = () => {
 304→    const newHeader = `Column ${data.headers.length + 1}`;
 305→    const newHeaders = [...data.headers, newHeader];
 306→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 307→    onChange({ ...data, headers: newHeaders, rows: newRows });
 308→  };
 309→
 310→  const removeColumn = (headerIndex: number) => {
 311→    if (data.headers.length <= 1) return;
 312→    const removedHeader = data.headers[headerIndex];
 313→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 314→    const newRows = data.rows.map((row) => {
 315→      const newRow: Record<string, string> = {};
 316→      newHeaders.forEach((h) => {
 317→        newRow[h] = row[h] ?? "";
 318→      });
 319→      return newRow;
 320→    });
 321→    onChange({ ...data, headers: newHeaders, rows: newRows });
 322→    void removedHeader;
 323→  };
 324→
 325→  const toggleUnit = (unit: string) => {
 326→    onChange({ ...data, units: { ...data.units, default: unit } });
 327→  };
 328→
 329→  return (
 330→    <div>
 331→      <div
 332→        style={{
 333→          display: "flex",
 334→          alignItems: "center",
 335→          gap: "8px",
 336→          marginBottom: "16px",
 337→        }}
 338→      >
 339→        <s-text tone="neutral">Unit system:</s-text>
 340→        {data.units.available.map((unit) => (
 341→          <button
 342→            key={unit}
 343→            type="button"
 344→            onClick={() => toggleUnit(unit)}
 345→            style={{
 346→              padding: "4px 12px",
 347→              borderRadius: "4px",
 348→              border: "1px solid",
 349→              borderColor: data.units.default === unit ? "#2c6ecb" : "#8c9196",
 350→              background: data.units.default === unit ? "#f0f7ff" : "#fff",
 351→              color: data.units.default === unit ? "#2c6ecb" : "#333",
 352→              fontWeight: data.units.default === unit ? 600 : 400,
 353→              cursor: "pointer",
 354→              fontSize: "13px",
 355→            }}
 356→          >
 357→            {unit}
 358→          </button>
 359→        ))}
 360→        <div style={{ marginLeft: "auto" }}>
 361→          <s-text tone="neutral">
 362→            {data.rows.length} rows · {data.headers.length} columns
 363→          </s-text>
 364→        </div>
 365→      </div>
 366→
 367→      <div style={{ overflowX: "auto" }}>
 368→        <table
 369→          style={{
 370→            width: "100%",
 371→            borderCollapse: "collapse",
 372→            fontSize: "14px",
 373→          }}
 374→        >
 375→          <thead>
 376→            <tr>
 377→              {data.headers.map((header, hi) => (
 378→                <th
 379→                  key={hi}
 380→                  style={{
 381→                    background: "#f6f6f7",
 382→                    border: "1px solid #e1e3e5",
 383→                    padding: "0",
 384→                    position: "relative",
 385→                    minWidth: "100px",
 386→                  }}
 387→                >
 388→                  <div
 389→                    style={{
 390→                      display: "flex",
 391→                      alignItems: "center",
 392→                      padding: "4px 4px 4px 8px",
 393→                    }}
 394→                  >
 395→                    <input
 396→                      ref={(el) => {
 397→                        headerInputRefs.current[hi] = el;
 398→                      }}
 399→                      value={header}
 400→                      onChange={(e) =>
 401→                        updateHeader(hi, (e.target as HTMLInputElement).value)
 402→                      }
 403→                      style={{
 404→                        flex: 1,
 405→                        border: "none",
 406→                        background: "transparent",
 407→                        fontWeight: 600,
 408→                        fontSize: "13px",
 409→                        color: "#202223",
 410→                        padding: "6px 4px",
 411→                        outline: "none",
 412→                        minWidth: "60px",
 413→                      }}
 414→                      placeholder={`Column ${hi + 1}`}
 415→                    />
 416→                    {data.headers.length > 1 && (
 417→                      <button
 418→                        type="button"
 419→                        onClick={() => removeColumn(hi)}
 420→                        title="Remove column"
 421→                        style={{
 422→                          background: "none",
 423→                          border: "none",
 424→                          cursor: "pointer",
 425→                          color: "#8c9196",
 426→                          padding: "2px 4px",
 427→                          borderRadius: "3px",
 428→                          fontSize: "14px",
 429→                          lineHeight: 1,
 430→                          flexShrink: 0,
 431→                        }}
 432→                        onMouseEnter={(e) => {
 433→                          (e.currentTarget as HTMLButtonElement).style.color = "#d82c0d";
 434→                        }}
 435→                        onMouseLeave={(e) => {
 436→                          (e.currentTarget as HTMLButtonElement).style.color = "#8c9196";
 437→                        }}
 438→                      >
 439→                        ×
 440→                      </button>
 441→                    )}
 442→                  </div>
 443→                </th>
 444→              ))}
 445→              <th
 446→                style={{
 447→                  background: "#f6f6f7",
 448→                  border: "1px solid #e1e3e5",
 449→                  padding: "8px",
 450→                  width: "48px",
 451→                }}
 452→              >
 453→                <button
 454→                  type="button"
 455→                  onClick={addColumn}
 456→                  title="Add column"
 457→                  style={{
 458→                    background: "none",
 459→                    border: "none",
 460→                    cursor: "pointer",
 461→                    color: "#2c6ecb",
 462→                    fontSize: "18px",
 463→                    lineHeight: 1,
 464→                    padding: "0 4px",
 465→                  }}
 466→                >
 467→                  +
 468→                </button>
 469→              </th>
 470→            </tr>
 471→          </thead>
 472→          <tbody>
 473→            {data.rows.map((row, ri) => (
 474→              <tr
 475→                key={ri}
 476→                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
 477→              >
 478→                {data.headers.map((header, hi) => (
 479→                  <td
 480→                    key={hi}
 481→                    style={{
 482→                      border: "1px solid #e1e3e5",
 483→                      padding: "0",
 484→                    }}
 485→                  >
 486→                    <input
 487→                      value={row[header] ?? ""}
 488→                      onChange={(e) =>
 489→                        updateCell(ri, header, (e.target as HTMLInputElement).value)
 490→                      }
 491→                      style={{
 492→                        width: "100%",
 493→                        border: "none",
 494→                        background: "transparent",
 495→                        padding: "8px 10px",
 496→                        fontSize: "13px",
 497→                        color: "#202223",
 498→                        outline: "none",
 499→                        boxSizing: "border-box",
 500→                      }}
 501→                      placeholder="—"
 502→                    />
 503→                  </td>
 504→                ))}
 505→                <td
 506→                  style={{
 507→                    border: "1px solid #e1e3e5",
 508→                    padding: "4px",
 509→                    textAlign: "center",
 510→                    background: ri % 2 === 0 ? "#fff" : "#fafbfb",
 511→                  }}
 512→                >
 513→                  <button
 514→                    type="button"
 515→                    onClick={() => removeRow(ri)}
 516→                    title="Remove row"
 517→                    style={{
 518→                      background: "none",
 519→                      border: "none",
 520→                      cursor: "pointer",
 521→                      color: "#8c9196",
 522→                      fontSize: "16px",
 523→                      lineHeight: 1,
 524→                      padding: "2px 6px",
 525→                      borderRadius: "3px",
 526→                    }}
 527→                    onMouseEnter={(e) => {
 528→                      (e.currentTarget as HTMLButtonElement).style.color = "#d82c0d";
 529→                    }}
 530→                    onMouseLeave={(e) => {
 531→                      (e.currentTarget as HTMLButtonElement).style.color = "#8c9196";
 532→                    }}
 533→                  >
 534→                    ×
 535→                  </button>
 536→                </td>
 537→              </tr>
 538→            ))}
 539→            <tr>
 540→              <td
 541→                colSpan={data.headers.length + 1}
 542→                style={{
 543→                  border: "1px solid #e1e3e5",
 544→                  padding: "8px 12px",
 545→                  background: "#f6f6f7",
 546→                }}
 547→              >
 548→                <button
 549→                  type="button"
 550→                  onClick={addRow}
 551→                  style={{
 552→                    background: "none",
 553→                    border: "none",
 554→                    cursor: "pointer",
 555→                    color: "#2c6ecb",
 556→                    fontSize: "13px",
 557→                    fontWeight: 500,
 558→                    padding: "0",
 559→                  }}
 560→                >
 561→                  + Add row
 562→                </button>
 563→              </td>
 564→            </tr>
 565→          </tbody>
 566→        </table>
 567→      </div>
 568→    </div>
 569→  );
 570→}
