 673→
 674→type LoaderData = Awaited<ReturnType<typeof loader>>;
 675→
 676→export default function SizeChartEditor() {
 677→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 678→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 679→
 680→  const saveFetcher = useFetcher<typeof action>();
 681→  const statusFetcher = useFetcher<typeof action>();
 682→  const assignmentFetcher = useFetcher<typeof action>();
 683→  const shopify = useAppBridge();
 684→
 685→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
 686→  const [category, setCategory] = useState(chart?.category ?? "general");
 687→  const [status, setStatus] = useState(chart?.status ?? "draft");
 688→  const [chartData, setChartData] = useState<ChartData>(
 689→    chart ? parseChartData(chart.data) : makeDefaultData()
 690→  );
 691→  const [assignments, setAssignments] = useState<Assignment[]>(initialAssignments);
 692→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 693→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 694→
 695→  const isSaving = saveFetcher.state !== "idle";
 696→  const isTogglingStatus = statusFetcher.state !== "idle";
 697→
 698→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 699→  useEffect(() => {
 700→    if (typeof window !== "undefined") {
 701→      const url = new URL(window.location.href);
 702→      if (url.searchParams.get("saved") === "1") {
 703→        shopify.toast.show("Chart created successfully");
 704→        url.searchParams.delete("saved");
 705→        window.history.replaceState({}, "", url.toString());
 706→      }
 707→    }
