import { useEffect, useRef, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, redirect } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
}

interface Assignment {
  id: string;
  assignmentType: string;
  assignmentValue: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;

  if (!id) throw new Response("Not found", { status: 404 });

  if (id === "new") {
    return {
      chart: null as null,
      assignments: [] as Assignment[],
      isNew: true,
    };
  }

  const chart = await db.sizeChart.findFirst({
    where: { id, shop },
    include: { assignments: true },
  });

  if (!chart) {
    throw new Response("Not found", { status: 404 });
  }

  return {
    chart: {
      id: chart.id,
      name: chart.name,
      category: chart.category,
      status: chart.status,
      data: chart.data,
      createdAt: chart.createdAt.toISOString(),
      updatedAt: chart.updatedAt.toISOString(),
    },
    assignments: chart.assignments.map((a) => ({
      id: a.id,
      assignmentType: a.assignmentType,
      assignmentValue: a.assignmentValue,
    })),
    isNew: false,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const id = params.id;
  if (!id) return { error: "Missing chart ID" };
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "save": {
        const name = formData.get("name") as string;
        const category = formData.get("category") as string;
        const status = formData.get("status") as string;
        const dataRaw = formData.get("data") as string;

        if (!name?.trim()) return { error: "Chart name is required" };

        let parsedData: ChartData;
        try {
          parsedData = JSON.parse(dataRaw) as ChartData;
        } catch {
          return { error: "Invalid chart data. Please try again." };
        }

        if (id === "new") {
          const chart = await db.sizeChart.create({
            data: {
              shop,
              name: name.trim(),
              category,
              status,
              data: JSON.stringify(parsedData),
            },
          });
          return redirect(`/app/size-charts/${chart.id}?saved=1`);
        }

        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!existing) return { error: "Chart not found" };

        await db.sizeChart.update({
          where: { id },
          data: {
            name: name.trim(),
            category,
            status,
            data: JSON.stringify(parsedData),
          },
        });
        return { ok: true, message: "Chart saved successfully" };
      }

      case "toggle-status": {
        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!chart) return { error: "Chart not found" };
        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.update({ where: { id }, data: { status: newStatus } });
        return {
          ok: true,
          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
          newStatus,
        };
      }

      case "add-assignment": {
        const assignmentType = formData.get("assignmentType") as string;
        const assignmentValue = formData.get("assignmentValue") as string;

        if (!assignmentValue?.trim()) {
          return { error: "Assignment value is required" };
        }

        await db.chartAssignment.upsert({
          where: {
            shop_sizeChartId_assignmentType_assignmentValue: {
              shop,
              sizeChartId: id,
              assignmentType,
              assignmentValue: assignmentValue.trim(),
            },
          },
          create: {
            shop,
            sizeChartId: id,
            assignmentType,
            assignmentValue: assignmentValue.trim(),
          },
          update: {},
        });
        return { ok: true, message: "Assignment added" };
      }

      case "remove-assignment": {
        const assignmentId = formData.get("assignmentId") as string;
        await db.chartAssignment.deleteMany({
          where: { id: assignmentId, shop },
        });
        return { ok: true, message: "Assignment removed" };
      }

      case "delete": {
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return redirect("/app/size-charts");
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const CATEGORIES = [
  { value: "general", label: "General" },
  { value: "tops", label: "Tops" },
  { value: "bottoms", label: "Bottoms" },
  { value: "dresses", label: "Dresses" },
  { value: "shoes", label: "Shoes" },
  { value: "kids", label: "Kids" },
  { value: "rings", label: "Rings" },
  { value: "sportswear", label: "Sportswear" },
];

const ASSIGNMENT_TYPES = [
  { value: "product", label: "Product ID" },
  { value: "collection", label: "Collection ID" },
  { value: "tag", label: "Product Tag" },
  { value: "product_type", label: "Product Type" },
  { value: "all", label: "All Products" },
];

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function makeDefaultData(): ChartData {
  return {
    headers: ["Size", "Chest", "Waist", "Hips"],
    units: { default: "in", available: ["in", "cm"] },
    rows: [
      { Size: "S", Chest: "", Waist: "", Hips: "" },
      { Size: "M", Chest: "", Waist: "", Hips: "" },
      { Size: "L", Chest: "", Waist: "", Hips: "" },
    ],
  };
}

function parseChartData(raw: string): ChartData {
  try {
    const parsed = JSON.parse(raw) as ChartData;
    if (
      Array.isArray(parsed.headers) &&
      parsed.units &&
      Array.isArray(parsed.rows)
    ) {
      return parsed;
    }
  } catch {
    // fall through
  }
  return makeDefaultData();
}

// ---------------------------------------------------------------------------
// Style constants (match dashboard design language)
// ---------------------------------------------------------------------------

const cardStyle: React.CSSProperties = {
  background: "#ffffff",
  border: "1px solid #e3e3e3",
  borderRadius: "12px",
  padding: "20px",
};

const sectionTitle: React.CSSProperties = {
  fontSize: "15px",
  fontWeight: 650,
  color: "#202223",
  margin: 0,
};

const inputStyle: React.CSSProperties = {
  width: "100%",
  border: "1px solid #8c9196",
  borderRadius: "8px",
  padding: "8px 12px",
  fontSize: "14px",
  color: "#202223",
  background: "#fff",
  boxSizing: "border-box" as const,
  outline: "none",
  fontFamily: "inherit",
};

const labelStyle: React.CSSProperties = {
  fontWeight: 600,
  fontSize: "13px",
  color: "#202223",
  marginBottom: "4px",
  display: "block",
};

const badgeStyle = (
  tone: "success" | "neutral" | "info" | "critical",
): React.CSSProperties => ({
  display: "inline-block",
  padding: "2px 8px",
  borderRadius: "10px",
  fontSize: "11px",
  fontWeight: 600,
  lineHeight: "18px",
  background:
    tone === "success"
      ? "#c8f9e8"
      : tone === "info"
        ? "#e4e5f7"
        : tone === "critical"
          ? "#fee2e2"
          : "#e4e5e7",
  color:
    tone === "success"
      ? "#0d6832"
      : tone === "info"
        ? "#3b3f8c"
        : tone === "critical"
          ? "#d82c0d"
          : "#6d7175",
});

function focusInput(el: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement) {
  el.style.borderColor = "#2c6ecb";
  el.style.boxShadow = "0 0 0 3px rgba(44,110,203,0.15)";
}

function blurInput(el: HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement) {
  el.style.borderColor = "#8c9196";
  el.style.boxShadow = "none";
}

// ---------------------------------------------------------------------------
// Table Editor Component — The Hero
// ---------------------------------------------------------------------------

interface TableEditorProps {
  data: ChartData;
  onChange: (data: ChartData) => void;
}

function TableEditor({ data, onChange }: TableEditorProps) {
  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const updateCell = (rowIndex: number, header: string, value: string) => {
    const newRows = data.rows.map((row, i) => {
      if (i !== rowIndex) return row;
      return { ...row, [header]: value };
    });
    onChange({ ...data, rows: newRows });
  };

  const updateHeader = (headerIndex: number, value: string) => {
    const oldHeader = data.headers[headerIndex];
    const newHeaders = data.headers.map((h, i) => (i === headerIndex ? value : h));
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      data.headers.forEach((h, i) => {
        const key = i === headerIndex ? value : h;
        newRow[key] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void oldHeader;
  };

  const addRow = () => {
    const emptyRow: Record<string, string> = {};
    data.headers.forEach((h) => {
      emptyRow[h] = "";
    });
    onChange({ ...data, rows: [...data.rows, emptyRow] });
  };

  const removeRow = (rowIndex: number) => {
    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
  };

  const addColumn = () => {
    const newHeader = `Column ${data.headers.length + 1}`;
    const newHeaders = [...data.headers, newHeader];
    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
    onChange({ ...data, headers: newHeaders, rows: newRows });
  };

  const removeColumn = (headerIndex: number) => {
    if (data.headers.length <= 1) return;
    const removedHeader = data.headers[headerIndex];
    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      newHeaders.forEach((h) => {
        newRow[h] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void removedHeader;
  };

  const toggleUnit = (unit: string) => {
    onChange({ ...data, units: { ...data.units, default: unit } });
  };

  return (
    <div>
      {/* Toolbar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          background: "#f6f6f7",
          border: "1px solid #e1e3e5",
          borderBottom: "none",
          borderRadius: "8px 8px 0 0",
          padding: "10px 14px",
        }}
      >
        <span
          style={{
            fontSize: "12px",
            fontWeight: 600,
            color: "#6d7175",
            marginRight: "4px",
            textTransform: "uppercase",
            letterSpacing: "0.04em",
          }}
        >
          Units
        </span>
        <div style={{ display: "flex", gap: "4px" }}>
          {data.units.available.map((unit) => (
            <button
              key={unit}
              type="button"
              onClick={() => toggleUnit(unit)}
              style={{
                padding: "3px 12px",
                borderRadius: "20px",
                border:
                  data.units.default === unit
                    ? "1.5px solid #2c6ecb"
                    : "1.5px solid #c9cccf",
                background:
                  data.units.default === unit ? "#2c6ecb" : "#ffffff",
                color:
                  data.units.default === unit ? "#ffffff" : "#6d7175",
                fontWeight: data.units.default === unit ? 700 : 500,
                cursor: "pointer",
                fontSize: "12px",
                lineHeight: "20px",
                transition: "all 0.12s ease",
                fontFamily: "inherit",
              }}
            >
              {unit}
            </button>
          ))}
        </div>
        <div
          style={{
            marginLeft: "auto",
            fontSize: "12px",
            color: "#8c9196",
            fontWeight: 500,
          }}
        >
          {data.rows.length} rows &middot; {data.headers.length} columns
        </div>
      </div>

      {/* Table container */}
      <div
        style={{
          border: "1px solid #e1e3e5",
          borderRadius: "0 0 8px 8px",
          overflow: "hidden",
          overflowX: "auto",
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
            tableLayout: "auto",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    borderBottom: "2px solid #e1e3e5",
                    borderRight:
                      hi < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    padding: "0",
                    position: "relative",
                    minWidth: "110px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "2px 6px 2px 10px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontWeight: 700,
                        fontSize: "12px",
                        color: "#202223",
                        padding: "8px 4px",
                        outline: "none",
                        minWidth: "60px",
                        textTransform: "uppercase",
                        letterSpacing: "0.04em",
                        fontFamily: "inherit",
                      }}
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#c9cccf",
                          padding: "2px 4px",
                          borderRadius: "4px",
                          fontSize: "15px",
                          lineHeight: 1,
                          flexShrink: 0,
                          transition: "color 0.1s",
                          fontFamily: "inherit",
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#d82c0d";
                          (e.currentTarget as HTMLButtonElement).style.background =
                            "#fee2e2";
                        }}
                        onMouseLeave={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#c9cccf";
                          (e.currentTarget as HTMLButtonElement).style.background =
                            "none";
                        }}
                      >
                        &times;
                      </button>
                    )}
                  </div>
                </th>
              ))}

              {/* Add column header cell */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  padding: "0",
                  width: "40px",
                  minWidth: "40px",
                }}
              >
                <button
                  type="button"
                  onClick={addColumn}
                  title="Add column"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "100%",
                    height: "100%",
                    minHeight: "38px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "20px",
                    lineHeight: 1,
                    padding: "0",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  +
                </button>
              </th>

              {/* Row actions header spacer */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  width: "36px",
                  minWidth: "36px",
                }}
              />
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{
                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
                  transition: "background 0.1s",
                }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    "#f0f5ff";
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
                }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    style={{
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(
                          ri,
                          header,
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "9px 10px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                        fontFamily: "inherit",
                      }}
                      onFocus={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow =
                          "inset 0 0 0 2px #2c6ecb";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "#f0f5ff";
                      }}
                      onBlur={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow = "none";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "transparent";
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column count spacer cell — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "0",
                    textAlign: "center",
                    width: "36px",
                    background: "transparent",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#c9cccf",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "4px 8px",
                      borderRadius: "4px",
                      transition: "color 0.1s, background 0.1s",
                      fontFamily: "inherit",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#d82c0d";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "#fee2e2";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#c9cccf";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "none";
                    }}
                  >
                    &times;
                  </button>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "0",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    display: "block",
                    width: "100%",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 600,
                    padding: "10px 14px",
                    textAlign: "left",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

